function seedTasks() {
  const examples = [
    [
      "Project quick review",
      "Quickly assess a new L2 project: product positioning, funding, token risk, competitors, and current market traction.",
      5,
    ],
    ["Token risk scan", "Scan a Base token for holder concentration, liquidity, owner permissions, tax/blacklist risk.", 8],
    [
      "Stablecoin yield scan",
      "Find stablecoin yield opportunities for 10,000 USDC, low-to-medium risk, 30-day horizon, and list exit conditions.",
      6,
    ],
  ];

  examples.forEach(([type, prompt, budget]) => {
    if (budget > state.wallet.balance) return;
    elements.taskType.value = type;
    elements.taskPrompt.value = prompt;
    elements.taskBudget.value = String(budget);
    createTask();
  });
}

function updateTask(id, next) {
  state.tasks = state.tasks.map((task) => (task.id === id ? { ...task, ...next } : task));
}

function acceptTask(id) {
  const task = state.tasks.find((item) => item.id === id);
  if (!task || task.status !== "open") return;
  updateTask(id, {
    status: "accepted",
    worker: state.agent.name,
    "Conclusion: More data needed. Opportunity score 5/10, risk score 5/10. Suggested action: watch first and avoid high-risk actions."
  );
}

function resetAll() {
  localStorage.removeItem(STORAGE_KEY);
  state = defaultState();
  render();
}

function render() {
  applyTranslations();
  renderNavigation();
  renderForms();
  renderAgent();
  renderMetrics();
  renderTasks(<truncated omitted_approx_tokens="1455" />fault();
  state.agent = readAgentForm();
  saveState();
  render();
});

function readAgentForm() {
  return {
    ...state.agent,
    name: elements.agentName.value.trim() || "local-agent",
    skill: elements.agentSkill.value,
    runtime: "Online Agent API",
    onlineApiBase: elements.onlineApiBase.value.trim() || "https://api.openai.com/v1",
    onlineModel: elements.onlineModel.value.trim() || "gpt-4.1-mini",
    onlineApiKey: elements.onlineApiKey.value.trim(),
  };
}

elements.taskForm.addEventListener("submit", (event) => {
  event.preventDefault();
  createTask();
});

document.body.addEventListener("click", (event) => {
  const watchButton = event.target.closest("[data-watch]");
  if (watchButton) {
    const item = reliableWatchlist.find((entry) => entry.symbol === watchButton.dataset.watch);
    if (!item) return;
    elements.taskType.value = item.taskType;
    elements.taskBudget.value = item.taskType === "Project deep research" ? "15" : "5";
    elements.taskPrompt.value = `Analyze ${item.symbol} / ${item.name}. Decide whether it is worth watching, and include opportunity score, risk score, main catalysts, key risks, suggested action, and data to monitor.`;
    window.scrollTo({ top: 0, behavior: "smooth" });
    return;
  }

  const button = event.target.closest("[data-action]");
  if (!button) return;
  const { action, id } = button.dataset;
  if (action === "accept") acceptTask(id);
  if (action === "run") runTask(id);
  if (action === "submit") submitTask(id);
  if (action === "pay") payTask(id);
  if (action === "refund") refundTask(id);
});

elements.seedBtn?.addEventListener("click", seedTasks);
elements.resetBtn.addEventListener("click", resetAll);
elements.testOnlineApiBtn.addEventListener("click", testOnlineApi);
elements.connectWalletBtn.addEventListener("click", () => {
  if (state.wallet.mode === "connected" && state.wallet.chainId !== baseChain.chainId) {
    switchToBase();
    return;
  }
  connectWallet();
});

